<script lang="ts">
import {onMount} from 'svelte';
type Status={installed:string;phase?:string;message?:string;version?:string};
let status:Status={installed:'Checking…'};let releases:{version:string;notes:string}[]=[];let error='';let statusError='';let busy=false;let requestKey='';
const labels:Record<string,string>={downloading:'Downloading the release…',verifying:'Verifying the release…',preparing:'Checking the new application…',backing_up:'Backing up your library…',restarting:'Starting the new version…',recovering:'Restoring the previous version…',ready:'Your library is ready.',recovered:'The previous version is running.',failed:'The update could not be installed.',needs_attention:'Update recovery needs attention.'};
$: running=['downloading','verifying','preparing','backing_up','restarting','recovering'].includes(status.phase||'');
async function call<T>(path:string,body?:unknown):Promise<T>{const r=await fetch(`/api/updates/${path}`,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const v=await r.json();if(!r.ok)throw new Error(v.error||'Could not check updates');return v;}
async function refresh(){try{status=await call<Status>('status');statusError='';}catch{statusError='Update status is temporarily unavailable. This page will keep checking.';}}
async function check(){busy=true;error='';try{await refresh();releases=(await call<{releases:{version:string;notes:string}[]}>('releases')).releases;}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function install(version:string){busy=true;error='';if(!requestKey)requestKey=crypto.randomUUID();try{status=await call<Status>('install',{version,request_key:requestKey});requestKey='';}catch(e){error=(e as Error).message;}finally{busy=false;}}
onMount(()=>{refresh();const timer=setInterval(refresh,3000);return()=>clearInterval(timer);});
</script>
<section class="updates"><h2>Application updates</h2><p>Installed version: <strong>{status.installed}</strong></p><p role="status">{status.message||labels[status.phase||'']||'Check for an approved release when you are ready.'}</p>{#if error||statusError}<p role="alert">{error||statusError}</p>{/if}<button class="library-button secondary" disabled={busy||running} onclick={check}>Check for updates</button>{#each releases as release}<article><h3>{release.version}</h3><p class="notes">{release.notes}</p><button class="library-button" disabled={busy||running||status.installed===release.version} onclick={()=>install(release.version)}>{status.installed===release.version?'Installed':'Install '+release.version}</button></article>{/each}<p class="library-help">Updates briefly pause saving. Keep this page open to follow progress. Your books and shelves are preserved.</p></section>
<style>@layer components{.updates{display:grid;gap:1rem;margin-top:2rem;max-width:44rem}.updates article{display:grid;gap:.75rem;padding:1rem;border:1px solid var(--app-line,var(--border))}.updates button{justify-self:start}.notes{white-space:pre-wrap;overflow-wrap:anywhere}}</style>
